package seed

import (
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// Manifest is generated by scripts/stories.py from the Git-tracked JSON files.
type Manifest struct {
	Version string         `json:"version"`
	Total   int            `json:"total"`
	Files   map[string]int `json:"files"`
}

func fingerprint(files []string, dataDir string) (string, *Manifest, error) {
	hash := sha256.New()
	for _, file := range files {
		raw, err := os.ReadFile(file)
		if err != nil {
			return "", nil, err
		}
		fmt.Fprintf(hash, "%s\x00", filepath.Base(file))
		hash.Write(raw)
		hash.Write([]byte{0})
	}
	version := fmt.Sprintf("sha256:%x", hash.Sum(nil))
	raw, err := os.ReadFile(filepath.Join(dataDir, "manifest.json"))
	if os.IsNotExist(err) {
		return version, nil, nil
	}
	if err != nil {
		return "", nil, err
	}
	var manifest Manifest
	if err := json.Unmarshal(raw, &manifest); err != nil {
		return "", nil, err
	}
	if version != manifest.Version || len(files) != len(manifest.Files) {
		return "", nil, fmt.Errorf("dataset manifest is stale; run python3 scripts/stories.py manifest")
	}
	for _, file := range files {
		raw, err := os.ReadFile(file)
		if err != nil {
			return "", nil, err
		}
		var entries []json.RawMessage
		if err := json.Unmarshal(raw, &entries); err != nil {
			return "", nil, err
		}
		expected, exists := manifest.Files[filepath.Base(file)]
		if !exists || expected != len(entries) {
			return "", nil, fmt.Errorf("dataset file count differs from manifest: %s", filepath.Base(file))
		}
	}
	return version, &manifest, nil
}
